-- Council Training: the Privacy Officer curriculum (2026-10-18).
--
-- Six modules for the Privacy Officer track (0058), about 10 minutes each,
-- as unpublished shells: title, scope, minutes, learning objectives (each
-- with a Bloom level), further reading and the blueprint that Draft with
-- AI turns into slides. Learners see them as "Coming soon" until each is
-- published.
--
-- From the Privacy Officer Track training blueprint: PIPA and the Strata
-- Property Act, distinguishing what the law requires from good practice,
-- and when to get the strata manager, council or a lawyer involved.
--
-- Safe to re-run: a module already seeded (and any edits to it) is left
-- alone. Paste the whole file into an empty SQL editor tab.

with seed (curriculum_key, order_index, title, summary, objectives, further_reading, blueprint) as (values
  ('po1', 1, 'Privacy Officer Role and Legal Framework',
   'Understand PIPA, the SPA, and the Privacy Officer''s responsibilities.',
   '[{"text": "Explain what PIPA protects and how it applies to a strata corporation", "bloom": "understand"}, {"text": "Describe the Privacy Officer''s responsibilities", "bloom": "understand"}, {"text": "Recognize when a privacy question requires escalation", "bloom": "remember"}]',
   '[{"title": "Personal Information Protection Act (PIPA)", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/03063_01", "note": "BC''s private-sector privacy law, which applies to strata corporations."}, {"title": "Strata Property Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/98043_00", "note": "Sections 35 and 36: the records a strata keeps and who can see them."}, {"title": "A Guide to B.C.''s Personal Information Protection Act (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1371", "note": "The Commissioner''s plain-language guide for organizations."}]',
   '[{"topic": "What is personal information?", "activity": "flip_cards", "teach": "Personal information is generally information about an identifiable individual. In a strata, this may include owner and tenant contact information; bylaw complaints and enforcement correspondence; information about disputes or accommodation requests; identifiable photographs, surveillance footage and access logs; and information about a person''s financial or personal circumstances."}, {"topic": "What is personal information?", "activity": "none", "teach": "Not every document containing a person''s name is confidential. The purpose, content, applicable law and circumstances decide how information should be handled."}, {"topic": "What does PIPA require?", "activity": "none", "teach": "PIPA governs how private-sector organizations in BC, strata corporations included, collect, use, disclose and protect personal information. It also sets requirements for access, correction, security and handling privacy complaints. The strata corporation must designate one or more individuals responsible for making sure it complies with PIPA, and make information about its privacy policies and practices available as required."}, {"topic": "What the Privacy Officer does", "activity": "accordion", "teach": "The Privacy Officer coordinates the strata''s privacy practices: maintaining privacy policies and procedures; advising council and the strata manager on privacy risks; coordinating personal-information requests and complaints; helping investigate and respond to privacy breaches; reviewing access controls, retention and service-provider practices; and recommending training and corrective action."}, {"topic": "What the Privacy Officer does", "activity": "none", "teach": "Appointing a Privacy Officer does not transfer the strata corporation''s legal responsibilities to that person. Council keeps its governance and oversight responsibilities."}, {"topic": "Privacy and strata governance", "activity": "none", "teach": "The Strata Property Act requires certain records to be kept and made available to people entitled to them. PIPA does not automatically override those access rights; the Privacy Officer helps the strata comply with both laws. When a matter is uncertain: record the question and the relevant facts, consult the strata manager, and seek legal advice where appropriate."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: an owner submits a bylaw complaint and demands a guarantee that their identity will never be disclosed. What should the Privacy Officer explain? A. All complaints are automatically confidential. B. The strata cannot accept complaints unless the owner agrees to disclosure. C. The strata will limit access and handle the information carefully, but cannot guarantee absolute confidentiality in every circumstance. D. The complaint must be distributed to all owners. Correct: C. Privacy requires appropriate safeguards, but disclosure may be needed for a fair process or required by law."}, {"topic": "Key takeaway", "activity": "none", "teach": "The Privacy Officer coordinates privacy compliance; council remains responsible for governance and oversight. When in doubt, document the question, consult the strata manager, and get legal advice where needed."}]'),
  ('po2', 2, 'Collecting, Using and Protecting Personal Information',
   'Apply privacy principles to owner information, complaints, and everyday administration.',
   '[{"text": "Identify common personal-information risks", "bloom": "remember"}, {"text": "Apply appropriate collection and use principles", "bloom": "apply"}, {"text": "Recognize practical safeguards for everyday strata records", "bloom": "remember"}]',
   '[{"title": "Personal Information Protection Act (PIPA)", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/03063_01", "note": "BC''s private-sector privacy law, which applies to strata corporations."}, {"title": "A Guide to B.C.''s Personal Information Protection Act (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1371", "note": "The Commissioner''s plain-language guide for organizations."}, {"title": "For private organizations (OIPC)", "url": "https://www.oipc.bc.ca/for-private-organizations/", "note": "The Commissioner''s guidance and forms for organizations, stratas included."}]',
   '[{"topic": "Collect only what is necessary", "activity": "accordion", "teach": "Before collecting information, ask: What specific purpose does the strata need to accomplish? Is the information reasonably necessary for that purpose? Is collection authorized under PIPA or another applicable law? Who needs access, and how long must it be kept?"}, {"topic": "Collect only what is necessary", "activity": "none", "teach": "Example: the strata collects information needed for its statutory records and legitimate administrative purposes, but does not gather extra personal details just because they might be useful someday."}, {"topic": "Consent and lawful authority", "activity": "none", "teach": "Consent is one basis for collecting, using or disclosing personal information, but PIPA also permits some activities without consent when its requirements are met. Being an owner in the strata is not blanket consent to every possible use of a person''s information. Information collected for building security, for example, should not automatically be reused to monitor a resident''s unrelated activities."}, {"topic": "Protect information every day", "activity": "accordion", "teach": "Good practices: limit access according to responsibilities; keep information accurate and correct errors appropriately; separate allegations from established facts; use approved storage and secure sharing; check recipients and attachments before sending emails; avoid unnecessary copies of sensitive documents; never share personal information through unapproved systems or public links."}, {"topic": "Protect information every day", "activity": "none", "teach": "Council members access information for legitimate strata purposes, not personal curiosity."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: a council member proposes sending around a spreadsheet of owners'' names, emails, phone numbers, vehicle details and emergency contacts to make communication easier. What should the Privacy Officer do first? A. Distribute it because everyone lives in the strata. B. Refuse all collection of personal information. C. Establish the purpose, determine the lawful authority and necessity of each field, and consider a more limited approach. D. Post it in a private social media group. Correct: C."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "An owner provides information for a specific bylaw complaint. Can the strata automatically use it for an unrelated community newsletter? No: the strata must establish an appropriate purpose and lawful authority for the new use."}, {"topic": "Key takeaway", "activity": "none", "teach": "Collect and use information for justified purposes, limit who can access it, and avoid unnecessary disclosure."}]'),
  ('po3', 3, 'Privacy vs. Access to Strata Records',
   'Balance privacy with statutory record-keeping and disclosure obligations.',
   '[{"text": "Explain the relationship between PIPA and the SPA''s access provisions", "bloom": "understand"}, {"text": "Recognize common statutory records and applicable deadlines", "bloom": "remember"}, {"text": "Follow a consistent process for handling access requests", "bloom": "apply"}]',
   '[{"title": "Strata Property Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/98043_00", "note": "Sections 35 and 36: the records a strata keeps and who can see them."}, {"title": "Strata Property Regulation", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/43_2000", "note": "How long each kind of strata record must be kept."}, {"title": "Information and record keeping in stratas (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/information-and-record-keeping", "note": "Strata records, access requests and privacy."}]',
   '[{"topic": "The strata''s record-keeping obligations", "activity": "none", "teach": "Strata Property Act section 35 requires the strata to keep specified records, including meeting minutes and vote results, financial records, bylaws and rules, contracts, correspondence, and owner and tenant information. The Act and the Strata Property Regulation set how long records must be kept. Sensitive information should not be deleted early just because it raises privacy concerns."}, {"topic": "Access rights and deadlines", "activity": "flip_cards", "teach": "Section 36 gives access to strata records to the people entitled to them, subject to the Act. Under the general timelines, records must generally be made available within two weeks, and bylaws and rules within one week. The Privacy Officer confirms the deadline and the applicant''s eligibility for each request. PIPA separately gives individuals the right to access their own personal information; that right is distinct from the SPA''s access to strata records."}, {"topic": "Balancing privacy with disclosure", "activity": "accordion", "teach": "Do not assume a document is confidential just because it concerns a complaint, dispute or individual owner. For every request: 1. Identify the exact records requested. 2. Confirm the applicant''s entitlement. 3. Identify the deadline. 4. Review the records for legal access requirements and privacy concerns. 5. Decide whether withholding or redaction is legally permitted. 6. Document the decision and provide the response securely."}, {"topic": "Balancing privacy with disclosure", "activity": "none", "teach": "Redaction is not automatically permitted in every case; get legal advice if the access right or the treatment of third-party information is uncertain. Minutes should record decisions and vote results accurately while avoiding unnecessary personal details. Legal advice and potentially privileged records need particular care."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: an owner requests council minutes containing a decision about a bylaw complaint against another resident. Can the strata automatically refuse the minutes because the matter is sensitive? No: the request must be assessed under the SPA and other applicable law."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "In the same scenario, can the Privacy Officer automatically remove every reference to the resident? No: any withholding or redaction must be legally justified in the circumstances."}, {"topic": "Key takeaway", "activity": "none", "teach": "Protect personal information while meeting the strata''s statutory record-keeping and access obligations."}]'),
  ('po4', 4, 'Surveillance, Security Systems and Digital Privacy',
   'Manage cameras, access logs, digital records, and security safeguards.',
   '[{"text": "Identify privacy risks associated with cameras and access-control systems", "bloom": "remember"}, {"text": "Apply basic digital security safeguards", "bloom": "apply"}, {"text": "Assess proposed surveillance and new technology before implementation", "bloom": "evaluate"}]',
   '[{"title": "Personal Information Protection Act (PIPA)", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/03063_01", "note": "BC''s private-sector privacy law, which applies to strata corporations."}, {"title": "A Guide to B.C.''s Personal Information Protection Act (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1371", "note": "The Commissioner''s plain-language guide for organizations."}, {"title": "For private organizations (OIPC)", "url": "https://www.oipc.bc.ca/for-private-organizations/", "note": "The Commissioner''s guidance and forms for organizations, stratas included."}]',
   '[{"topic": "Surveillance must be justified", "activity": "none", "teach": "Cameras, video recordings, fob systems and access logs can collect personal information about owners, tenants, visitors and contractors. Before introducing surveillance, council should identify a specific, verifiable concern and assess whether surveillance is reasonably necessary and authorized under PIPA."}, {"topic": "Surveillance must be justified", "activity": "none", "teach": "Consider less intrusive options first, such as better lighting, locks or access controls. Limit surveillance to appropriate areas, document its purpose, and set an appropriate policy and, where needed, a bylaw. Don''t assume the Standard Bylaws apply as written: many stratas have amended them."}, {"topic": "Limit access and retention", "activity": "accordion", "teach": "Surveillance information must not be used indiscriminately: restrict access to authorized people; record who accesses or exports recordings where appropriate; use footage only for justified purposes; keep it for a reasonable, defined period; and preserve relevant recordings when an incident needs investigation or legal proceedings. The OIPC''s strata guidance discusses short retention for routine footage, with longer retention where a specific incident justifies it."}, {"topic": "Protect digital records", "activity": "none", "teach": "PIPA section 34 requires reasonable security arrangements to protect personal information. Practical measures: individual user accounts, strong authentication, appropriate access permissions, secure sharing, prompt removal of access people no longer need, and approved storage. A new software platform or AI tool should not receive sensitive owner information until the strata has assessed its suitability, data handling, access controls and contract terms."}, {"topic": "Assess new systems before adoption", "activity": "flip_cards", "teach": "Before approving a new system, ask: what information does it collect, why is it needed, who can access it, where is it stored, and how will it be kept or deleted? A privacy impact assessment (PIA) is a useful way to identify risks, but it is not a legal requirement for every strata technology purchase."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: a council member wants to use fob logs to monitor a resident''s movements because the resident may be breaking a bylaw. What should the Privacy Officer recommend? A. Approve the monitoring because the strata owns the system. B. Share the logs with all owners. C. Assess whether the proposed use is authorized and reasonably necessary for a specific purpose. D. Delete all access logs immediately. Correct: C."}, {"topic": "Key takeaway", "activity": "none", "teach": "Having access to a security system does not give council unrestricted authority to use the information it collects."}]'),
  ('po5', 5, 'Privacy Requests, Complaints and Breaches',
   'Respond appropriately to information requests, complaints, and incidents.',
   '[{"text": "Distinguish a PIPA access request from an SPA records request", "bloom": "understand"}, {"text": "Follow a consistent privacy complaint process", "bloom": "apply"}, {"text": "Identify the first steps in responding to a privacy breach", "bloom": "remember"}]',
   '[{"title": "Personal Information Protection Act (PIPA)", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/03063_01", "note": "BC''s private-sector privacy law, which applies to strata corporations."}, {"title": "Privacy breaches: tools and resources for the private sector (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1361", "note": "The four steps after a breach, with a checklist and notification tool."}, {"title": "A Guide to B.C.''s Personal Information Protection Act (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1371", "note": "The Commissioner''s plain-language guide for organizations."}]',
   '[{"topic": "Personal-information requests", "activity": "accordion", "teach": "PIPA sections 23 and 24 cover requests to access and correct personal information. When a request arrives: 1. Record the date and clarify the scope. 2. Verify the requester''s identity and authority where appropriate. 3. Identify the information and systems involved. 4. Review the access rights and exceptions that apply. 5. Respond within the deadline."}, {"topic": "Personal-information requests", "activity": "none", "teach": "Under PIPA section 29 the general response period is 30 days, subject to the Act''s provisions for extensions and other circumstances. Don''t apply the SPA''s record-access deadlines to a PIPA request: they are different rights with different timelines."}, {"topic": "Privacy complaints", "activity": "none", "teach": "PIPA requires an organization to have a process for responding to privacy complaints and to make information about it available on request. The Privacy Officer acknowledges the complaint, establishes the facts, restricts access to those who need to investigate, documents the findings, and recommends corrective action where appropriate. If the complaint concerns the Privacy Officer or someone involved in the investigation, consider an independent reviewer."}, {"topic": "Responding to a breach", "activity": "accordion", "teach": "Examples of breaches: misdirected emails, unauthorized access to owner records, exposed cloud folders, lost devices, and inappropriate sharing of surveillance footage. The response: Contain (stop unauthorized access, secure affected systems, preserve evidence). Assess (the information involved, affected people, likely recipients and potential harm). Escalate and notify as appropriate (inform the right council representative and professionals; assess notification obligations under current law and OIPC guidance). Document and improve (record actions and decisions, then fix the cause)."}, {"topic": "Responding to a breach", "activity": "none", "teach": "Don''t assume every breach has the same notification requirements: assess the specific circumstances and current legal obligations."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: a council member accidentally emails a spreadsheet with owners'' contact details and strata fee arrears to all owners. What should happen first? A. Wait for a complaint. B. Contain the disclosure, escalate the incident, assess potential harm, and document the response. C. Delete the original spreadsheet and take no further action. Correct: B."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Should the strata automatically notify every affected person in exactly the same way after every breach? No: notification decisions depend on the circumstances, applicable legal requirements and appropriate professional advice."}, {"topic": "Key takeaway", "activity": "none", "teach": "Respond promptly: contain the breach, assess the risk, and document the decisions."}]'),
  ('po6', 6, 'Building a Privacy Program for Your Strata',
   'Implement policies, retention practices, vendor safeguards, and ongoing oversight.',
   '[{"text": "Identify the basic components of a privacy program", "bloom": "remember"}, {"text": "Apply appropriate retention and destruction practices", "bloom": "apply"}, {"text": "Oversee privacy risks involving strata managers and service providers", "bloom": "apply"}]',
   '[{"title": "Getting Accountability Right with a Privacy Management Program (OIPC)", "url": "https://www.oipc.bc.ca/documents/guidance-documents/1368", "note": "What a privacy program contains and how to keep it current."}, {"title": "Personal Information Protection Act (PIPA)", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/03063_01", "note": "BC''s private-sector privacy law, which applies to strata corporations."}, {"title": "Strata Property Regulation", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/43_2000", "note": "How long each kind of strata record must be kept."}]',
   '[{"topic": "A practical privacy framework", "activity": "accordion", "teach": "The strata should have: a written privacy policy and complaint process; current Privacy Officer contact information; procedures for requests and breaches; appropriate access controls; a record retention and destruction schedule; privacy and security requirements for service providers; and basic training for council members and relevant staff. The goal is a workable system, not a complicated policy manual."}, {"topic": "Retaining and destroying records", "activity": "none", "teach": "PIPA section 35 requires personal information used to make a decision that directly affects someone to be kept for at least one year, subject to the Act, and addresses destroying or de-identifying it once keeping it is no longer reasonably necessary. The SPA and the Strata Property Regulation set separate retention periods for strata records; legal obligations take priority over an internal schedule. The Privacy Officer helps council tell apart statutory records, operational records, surveillance footage and unnecessary duplicate copies."}, {"topic": "Managing property managers and contractors", "activity": "accordion", "teach": "The strata remains responsible for personal information under its control, even when a service provider holds or processes it. Check that contracts cover: permitted use of personal information; access controls and security; subcontractor access; privacy incident reporting; getting records back when the contract ends; and retention, return and secure destruction."}, {"topic": "Managing property managers and contractors", "activity": "none", "teach": "When the property manager changes, plan the handover so required records are preserved, access is controlled, and unnecessary copies are dealt with appropriately."}, {"topic": "Privacy as routine governance", "activity": "flip_cards", "teach": "Monthly or as needed: review requests, complaints, incidents and proposed new uses of personal information. Annually: review policies, access permissions, retention practices and service-provider arrangements. When circumstances change: assess new systems, investigate incidents and update procedures."}, {"topic": "Check your understanding", "activity": "knowledge_check", "teach": "Scenario: the strata changes property managers. The outgoing manager holds owner records, bylaw correspondence, financial records and copies of identification documents. What should the Privacy Officer do? A. Let the outgoing manager keep everything indefinitely. B. Demand immediate deletion of all records. C. Coordinate a documented handover, preserve the records the strata must or may keep, and establish what is returned, kept or securely destroyed. D. Let the incoming manager start from scratch. Correct: C. Privacy safeguards are maintained while meeting record-keeping obligations."}, {"topic": "Key takeaway", "activity": "none", "teach": "Privacy compliance is an ongoing governance process, supported by clear procedures, secure systems and appropriate oversight."}]')
)
insert into public.training_modules
  (track_id, order_index, title, summary, estimated_minutes, curriculum_key, objectives, further_reading, blueprint)
select t.id, s.order_index, s.title, s.summary, 10, s.curriculum_key,
       s.objectives::jsonb, s.further_reading::jsonb, s.blueprint::jsonb
from seed s
join public.training_tracks t on t.code = 'privacy_officer'
where not exists (select 1 from public.training_modules m where m.curriculum_key = s.curriculum_key);
